#' Estimate Phenological Onset Shift Volume
#'
#' Calculates the bidirectional early-season emergence shift volume between a
#' focal/shifted posterior density matrix and a reference posterior density matrix
#' on the continuous Day of Biological Year (DOBY) timeline.
#'
#' @param sim_mat A numeric matrix (`n_grid x n_sims`, typically `365 x 1000`) of normalized posterior density curves for the focal or shifted scenario, generated by [simulate_posterior_density()].
#' @param ref_sim_mat A numeric matrix (`n_grid x n_sims`, typically `365 x 1000`) of normalized posterior density curves for the reference scenario, generated by [simulate_posterior_density()].
#' @param threshold_fraction Numeric, density threshold fraction to filter winter tail noise (default = `0.05`).
#' @return A list containing the posterior `Mean`, `Lower_CI` (2.5%), `Upper_CI` (97.5%), `Posterior_Draws`, and the reference biological minimum day `D_min`.
#' @examples
#' data(sim_carabids)
#' mod <- mgcv::gam(
#'   Count ~ s(DOY, bs = "cc", k = 10) + ti(DOY, Latitude, bs = c("cc", "cr"), k = c(8, 4)) +
#'     s(Latitude, k = 4) + offset(LogEffort),
#'   family = poisson(), data = sim_carabids,
#'   knots = list(DOY = c(0.5, 365.5))
#' )
#' sim_south <- simulate_posterior_density(
#'   mod, create_newdata(mod, Latitude = "5%"), n_sims = 100, warnings = FALSE
#' )
#' sim_ref <- simulate_posterior_density(
#'   mod, create_newdata(mod, Latitude = "mean"), n_sims = 100, warnings = FALSE
#' )
#' estimate_onset(sim_south, sim_ref)$Mean
#' @export
estimate_onset <- function(sim_mat, ref_sim_mat, threshold_fraction = 0.05) {
  grid_ref <- get_doy_grid(ref_sim_mat)
  grid_sim <- get_doy_grid(sim_mat)
  if (grid_sim$n_rows != grid_ref$n_rows) {
    stop("'sim_mat' and 'ref_sim_mat' must have the same number of temporal rows.")
  }

  base_dens <- rowMeans(ref_sim_mat)
  origin <- compute_doby_origin(base_dens, grid_ref$doy)
  shift_order <- origin$shift_order

  n_draws <- min(ncol(sim_mat), ncol(ref_sim_mat))
  res <- numeric(n_draws)

  for (i in seq_len(n_draws)) {
    td_shift <- sim_mat[shift_order, i]
    rd_shift <- ref_sim_mat[shift_order, i]

    # 1. Filter out winter tail noise
    active_mask <- (td_shift > threshold_fraction * max(td_shift)) |
                   (rd_shift > threshold_fraction * max(rd_shift))

    # 2. Identify curve crossings
    diff_sign <- sign(td_shift - rd_shift)
    diff_sign[diff_sign == 0] <- 1
    crossings <- which(diff(diff_sign) != 0)

    # 3. Locate first valid crossing within active season
    valid_crossings <- crossings[active_mask[crossings] | active_mask[crossings + 1]]
    if (length(valid_crossings) == 0) {
      first_cross <- which.max(abs(cumsum(td_shift) - cumsum(rd_shift)))
    } else {
      first_cross <- valid_crossings[1]
    }

    # Positive value indicates earlier emergence in sim_mat relative to ref_sim_mat
    cdiff <- cumsum(td_shift) - cumsum(rd_shift)
    res[i] <- cdiff[first_cross]
  }

  return(list(
    Mean = mean(res),
    Lower_CI = stats::quantile(res, 0.025),
    Upper_CI = stats::quantile(res, 0.975),
    Posterior_Draws = res,
    D_min = origin$D_min
  ))
}
